3	/// Switch by Speaker's planner (road map "creator-jobs" SW2a, spec §11
4	/// SW-20…SW-25): which microphone is active on a 10 ms grid, the shots those
5	/// turns make on the angle tracks, and every refusal named at once. Nothing
6	/// here is visible yet; SW2b's sheet and tool write the shots onto a Program
7	/// track.
8	///
9	/// Pure (SW-25): `defaults`, `plan`, `labels` and `shots` read no document,
10	/// file or clock. `read` (`SpeakerSwitch+Read.swift`) is the one reader, and
11	/// the series it builds are `ClipLevelSeries`'. Names no `rc_*` but
12	/// `ReelTime.snapToFrame` and `ReelTime.format`.
13	enum SpeakerSwitch {
14	    static let actionName = "Switch by Speaker"
15	    static let maxAngles = 9
16	
17	    /// What a qualifying crosstalk turn does: show the wide, or hold.
18	    enum Crosstalk: String { case wide, hold }
19	
20	    /// Seconds and dB; the defaults are SW-S4's (SW-21) and SW-22's drafts.
21	    struct Settings: Equatable {
22	        var minShot = 2.0, minTurn = 1.0, lead = 0.2, crosstalkMin = 1.0, bridge = 0.5
23	        var crosstalk: Crosstalk = .wide
