126	    /// A `detach_audio` half: the sound of a file with pictures.
127	    static func isDetachedSound(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
128	        !clip.enabled.video && clip.linked != nil && snapshot.media(for: clip)?.hasVideo == true
129	    }
