137	    /// A media clip that sounds, by the snapshot alone (no plan here): its
138	    /// media has audio, its sound is on, and it is no detached camera sound.
139	    static func playsSound(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
140	        guard case .media = clip.source, clip.enabled.audio,
141	            snapshot.media(for: clip)?.hasAudio == true
142	        else { return false }
143	        return !isDetachedSound(clip, in: snapshot)
144	    }
