548	        } else {
549	            let named = Set(pairing.speakers.compactMap(\.mic))
550	            microphoneTracks = front.filter { track in
551	                named.contains(track) && selection.contains {
552	                    guard $0.track == track, case .media = $0.source, $0.enabled.audio else {
553	                        return false
554	                    }
555	                    return snapshot.media(for: $0)?.hasAudio == true
556	                }
557	            }
558	        }
559	
560	        let angles = implied.angles.map { track in
561	            AngleTrack(
562	                track: track,
563	                clips: SwitchAngle.pictureClips(on: track, in: snapshot).map {
564	                    Span(clip: $0.id, start: $0.start, end: $0.end)
565	                })
566	        }
567	        let angleClips = selection.filter {
568	            implied.angles.contains($0.track) && isPicture($0, in: snapshot)
569	        }
