571	            ?? (angleClips.map(\.start).min() ?? 0, angleClips.map(\.end).max() ?? 0)
572	        let step = stepTicks
573	        let count = step > 0 ? Int(max(0, span.1 - span.0) / step) : 0
574	
575	        let segments = AudioNormalize.audioSegments(in: plan)
576	        let voiced = SileroVAD.isAvailable
577	        var loudness: [UInt32: MediaLoudness] = [:]
578	        var speech: [UInt32: [Float]] = [:]
579	        var problems: [String] = []
580	        var microphones: [Microphone] = []
581	        for track in microphoneTracks {
582	            let clips = selection.filter { $0.track == track && segments[$0.id] != nil }
583	                .sorted { $0.start < $1.start }
584	            let media = clips.compactMap { segments[$0.id]?.first?.media }
585	            for id in media where loudness[id] == nil {
586	                if let read = document.cacheDirectory.flatMap({
587	                    MediaImporter.loadLoudness(for: id, in: $0)
588	                }) { loudness[id] = read }
589	            }
590	            if voiced {
591	                for id in media where speech[id] == nil {
592	                    if let read = document.cacheDirectory.flatMap({
593	                        MediaImporter.loadSpeech(for: id, in: $0)
594	                    }) { speech[id] = read }
595	                }
596	            }
597	            let unread = "The microphone on track \(track) is still being analysed — its "
598	            var pending = false
599	            if media.contains(where: { loudness[$0] == nil }) {
600	                pending = true
601	                problems.append(unread + "loudness has not been measured yet. Try again in a moment.")
602	            } else if voiced, media.contains(where: { speech[$0] == nil }) {
603	                pending = true
604	                problems.append(unread + "speech has not been detected yet. Try again in a moment.")
605	            }
606	            guard !pending, voiced else {
607	                microphones.append(Microphone(track: track, level: [], voice: [], covered: []))
608	                continue
609	            }
610	            var energy = [Double](repeating: 0, count: count)
611	            var voice = [Float](repeating: 0, count: count)
612	            var covered = [Bool](repeating: false, count: count)
613	            for clip in clips {
614	                guard let own = segments[clip.id], let first = own.first,
615	                    let cache = loudness[first.media]
616	                else { continue }
617	                let cited = own.filter { $0.media == first.media }
618	                let pivots = cited.map { MediaPeaks.reversedPivot(for: $0, in: snapshot) }
619	                let low = cited.map(\.start).min() ?? 0
620	                let high = cited.map { $0.start + $0.duration }.max() ?? 0
621	                let k0 = max(0, Int(MediaPeaks.bucketIndex(low - span.0, bucket: step)))
622	                let k1 = min(count, Int(MediaPeaks.bucketIndex(high - span.0 + step - 1, bucket: step)))
623	                guard k1 > k0 else { continue }
624	                let origin = span.0 + Ticks(k0) * step
625	                let read = ClipLevelSeries.energies(
626	                    cache, segments: cited, pivots: pivots, matrix: .init(clip.audio),
627	                    from: origin, count: k1 - k0)
628	                let p = ClipLevelSeries.voice(
629	                    speech[first.media] ?? [], segments: cited, pivots: pivots, from: origin,
630	                    count: k1 - k0)
