632	                    energy[k0 + j] = read.energy[j]
633	                    voice[k0 + j] = p[j]
634	                    covered[k0 + j] = true
635	                }
636	            }
637	            microphones.append(
638	                Microphone(
639	                    track: track, level: ClipLevelSeries.levels(energy), voice: voice,
640	                    covered: covered))
641	        }
642	        if !voiced {
643	            problems.append(
644	                "Speech detection is unavailable on this Mac, so Switch by Speaker cannot tell "
645	                    + "who is talking.")
646	        }
647	        // SW-84: the faces mode's angles, their problems after the microphones'.
648	        var faces: [FaceAngle] = []
649	        if mode(pairing) == .faces {
650	            let read = readFaces(
651	                from: document, angles: angles, pairing: pairing, from: span.0, count: count)
652	            faces = read.faces
653	            problems += read.problems
654	        }
655	        return Input(
656	            from: span.0, to: span.1, fps: snapshot.canvas.fps, angles: angles,
657	            microphones: microphones, pairing: pairing, problems: problems,
658	            clipCount: ShotSplit.clipCount(document.project.snapshot), settings: settings,
659	            faces: faces)
660	    }
