769	    /// The nearest-rank percentile `sorted[⌈p·n⌉ − 1]`; nil for no values.
770	    static func percentile(_ values: [Double], _ p: Double) -> Double? {
771	        guard !values.isEmpty else { return nil }
772	        let sorted = values.sorted()
773	        let rank = Int((p * Double(sorted.count) - 1e-9).rounded(.up))
774	        return sorted[min(sorted.count - 1, max(0, rank - 1))]
775	    }
