779	    /// One label per step. Every microphone's series must be the same length.
780	    static func labels(_ microphones: [Microphone], settings: Settings) -> [Label] {
781	        activeSets(microphones, settings: settings).map { active in
782	            switch active.count {
783	            case 0: return .nobody
784	            case 1: return .person(active[0])
