790	    /// The microphone tracks active on each step (SW-21), a dominant one alone.
791	    static func activeSets(_ microphones: [Microphone], settings: Settings) -> [[UInt32]] {
792	        let count = microphones.map(\.level.count).min() ?? 0
793	        let threshold = settings.voiceThreshold
794	        // P and F per microphone; a microphone with no speech is never active.
795	        let gauges: [(p: Double, f: Double)?] = microphones.map { mic in
796	            var speech: [Double] = []
797	            var quiet: [Double] = []
798	            for k in 0..<count where mic.covered[k] {
799	                if mic.voice[k] >= threshold { speech.append(mic.level[k]) } else {
800	                    quiet.append(mic.level[k])
801	                }
802	            }
803	            guard let p = percentile(speech, 0.9) else { return nil }
804	            return (p, percentile(quiet, 0.1) ?? -.infinity)
805	        }
806	        var out: [[UInt32]] = []
807	        out.reserveCapacity(count)
808	        for k in 0..<count {
809	            var active: [(track: UInt32, over: Double)] = []
810	            for (index, mic) in microphones.enumerated() {
811	                guard let gauge = gauges[index], mic.covered[k], mic.voice[k] >= threshold
812	                else { continue }
813	                let level = mic.level[k]
814	                guard level >= gauge.p - settings.bleedDB,
815	                    level >= gauge.f + settings.floorMarginDB
816	                else { continue }
817	                active.append((mic.track, level - gauge.p))
818	            }
819	            if active.count >= 2, let top = active.max(by: { $0.over < $1.over }),
820	                active.allSatisfy({ $0.track == top.track
821	                    || top.over - $0.over >= settings.dominanceDB })
822	            {
823	                active = [top]
824	            }
825	            out.append(active.map(\.track))
826	        }
827	        return out
828	    }
