848	    /// SW-22 (a), the crosstalk half: each maximal stretch of non-crosstalk runs lying between two
849	    /// crosstalk runs, shorter than `bridge` in total, becomes crosstalk; the runs it joins merge.
850	    static func bridgingCrosstalk(_ runs: [Run], under bridge: Ticks) -> [Run] {
851	        var out: [Run] = []
852	        var index = 0
853	        while index < runs.count {
854	            let run = runs[index]
855	            if run.label != .crosstalk, var last = out.last, last.label == .crosstalk,
856	                let next = runs[index...].firstIndex(where: { $0.label == .crosstalk }),
857	                Ticks(runs[next].start - run.start) * stepTicks < bridge
858	            {
859	                last.end = runs[next].end
860	                out[out.count - 1] = last
861	                index = next + 1
862	                continue
863	            }
864	            out.append(run)
865	            index += 1
866	        }
867	        return out
868	    }
