85	    /// The angles, microphones and pairing a selection implies, front first.
86	    static func defaults(selection: [ClipSnapshot], in snapshot: ProjectSnapshot)
87	        -> (angles: [UInt32], microphones: [UInt32], pairing: Pairing)
88	    {
89	        let front = snapshot.tracks.reversed().map(\.id)
90	        func holds(_ track: UInt32, _ test: (ClipSnapshot) -> Bool) -> Bool {
91	            selection.contains { $0.track == track && test($0) }
92	        }
93	        let angles = front.filter { holds($0) { isPicture($0, in: snapshot) } }
94	        let files = front.filter {
95	            holds($0) { playsSound($0, in: snapshot) && snapshot.media(for: $0)?.hasVideo == false }
96	        }
97	        let microphones = files.isEmpty
98	            ? angles.filter { holds($0) { playsSound($0, in: snapshot) } } : files
99	
100	        var speakers: [Speaker] = []
101	        var used: Set<UInt32> = []
102	        for mic in microphones where angles.contains(mic) {
103	            used.insert(mic)
104	        }
105	        var free = angles.filter { !used.contains($0) }.makeIterator()
106	        for mic in microphones {
107	            if angles.contains(mic) {
108	                speakers.append(Speaker(mic: mic, angle: mic))
109	            } else if let angle = free.next() {
110	                used.insert(angle)
111	                speakers.append(Speaker(mic: mic, angle: angle))
112	            } else {
113	                speakers.append(Speaker(mic: mic, angle: nil))
114	            }
115	        }
116	        let left = angles.filter { !used.contains($0) }
117	        // SW-83: one microphone shared by every angle, and no wide (the faces mode).
118	        if microphones.count == 1, angles.count >= 2, let mic = microphones.first {
119	            return (angles, microphones,
120	                    Pairing(speakers: angles.map { Speaker(mic: mic, angle: $0) }, wide: nil))
121	        }
122	        return (angles, microphones,
123	                Pairing(speakers: speakers, wide: left.count == 1 ? left.first : nil))
124	    }
