131	    /// A media clip with a picture that may make its track an angle.
132	    static func isPicture(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
133	        guard case .media = clip.source, snapshot.sourceSize(of: clip) != nil else { return false }
134	        return !(clip.enabled.video == false && clip.linked != nil)
135	    }
