146	    // MARK: - The plan
147	
148	    static func plan(_ input: Input) -> Plan {
149	        let refusals = refusals(input)
150	        if !refusals.isEmpty { return .refused(refusals) }
151	        let step = stepTicks
152	        let count = step > 0 ? Int(max(0, input.to - input.from) / step) : 0
153	        let faces = mode(input.pairing) == .faces
154	        let all = faces
155	            ? faceLabels(input)
156	            : labels(input.microphones.filter { $0.level.count == count }, settings: input.settings)
157	        let planned = shots(
158	            labels: all, from: input.from, to: input.to, fps: input.fps,
159	            pairing: faces ? facePairing(input.pairing) : input.pairing,
160	            angles: input.angles, settings: input.settings)
161	        let added = clipsAdded(planned, angles: input.angles, from: input.from, to: input.to)
162	        let most = Int(RC_MAX_CLIPS)
163	        if input.clipCount + added > most {
164	            return .refused([
165	                "Switch by Speaker would add \(added) clips to \(input.clipCount); the most is "
166	                    + "\(most) — raise the minimum shot."
167	            ])
168	        }
169	        return .planned(shots: planned, added: added)
170	    }
