172	    /// SW-24's list, in its order; empty when nothing is refused.
173	    static func refusals(_ input: Input) -> [String] {
174	        var out: [String] = []
175	        let angles = input.angles.map(\.track)
176	        if angles.count < 2 {
177	            out.append(
178	                "Switch by Speaker needs at least two angles: tracks holding a selected clip "
179	                    + "with a picture.")
180	        }
181	        if angles.count > maxAngles {
182	            out.append(
183	                "Switch by Speaker takes at most nine angles; \(angles.count) tracks hold a "
184	                    + "selected clip with a picture.")
185	        }
186	        let microphones = input.microphones.map(\.track)
187	        let faces = mode(input.pairing) == .faces
188	        // SW-83: in the faces mode a speaker on the wide takes no part.
189	        for speaker in input.pairing.speakers
190	        where !(faces && speaker.angle != nil && speaker.angle == input.pairing.wide) {
191	            guard let mic = speaker.mic, microphones.contains(mic) else {
192	                let track = speaker.angle ?? speaker.mic ?? 0
193	                out.append("The speaker on track \(track) has no microphone.")
194	                continue
195	            }
196	            if speaker.angle.map({ !angles.contains($0) }) ?? true {
197	                out.append("The microphone on track \(mic) has no angle to show its speaker.")
198	            }
199	        }
200	        var counted: [UInt32] = []
201	        for mic in input.pairing.speakers.compactMap(\.mic) where !faces && !counted.contains(mic) {
202	            counted.append(mic)
203	            let n = input.pairing.speakers.filter { $0.mic == mic }.count
204	            if n > 1 {
205	                out.append(
206	                    "Track \(mic) is the microphone for \(n) speakers; each person needs their "
207	                        + "own microphone.")
208	            }
209	        }
210	        out += input.problems
211	        let count = stepTicks > 0 ? Int(max(0, input.to - input.from) / stepTicks) : 0
212	        let a = ReelTime.format(input.from, fps: input.fps, frames: true)
213	        let b = ReelTime.format(input.to, fps: input.fps, frames: true)
214	        out += silentMicrophones(input)
215	        // SW-84: a read angle with no step whose mouth can be read.
216	        for angle in input.faces where angle.activity.count == count
217	            && !angle.activity.contains(where: { $0 != nil })
218	        {
219	            out.append(
220	                "The camera on track \(angle.track) shows no face whose mouth can be read between "
221	                    + "\(a) and \(b), so it never says who is talking.")
222	        }
223	        if let gap = firstGap(input.angles, from: input.from, to: input.to) {
224	            out.append(
225	                "No angle has a picture between "
226	                    + "\(ReelTime.format(gap.from, fps: input.fps, frames: true)) and "
227	                    + "\(ReelTime.format(gap.to, fps: input.fps, frames: true)).")
228	        }
229	        return out
230	    }
