281	    /// SW-24's N: per shot, the angle clips it overlaps (the later one
282	    /// taking over where two overlap, SW-15 (d)), plus a split for each
283	    /// angle clip straddling `from` and each straddling `to`.
284	    static func clipsAdded(_ shots: [Shot], angles: [AngleTrack], from: Ticks, to: Ticks) -> Int {
285	        var n = 0
286	        for shot in shots {
287	            guard let angle = angles.first(where: { $0.track == shot.angle }) else { continue }
288	            let crossing = angle.clips.filter { $0.end > shot.start && $0.start < shot.end }
289	            for (index, clip) in crossing.enumerated() {
290	                let next = index + 1 < crossing.count ? crossing[index + 1].start : shot.end
291	                if min(clip.end, next, shot.end) > max(clip.start, shot.start) { n += 1 }
292	            }
293	        }
294	        for clip in angles.flatMap(\.clips) {
295	            if clip.start < from && from < clip.end { n += 1 }
296	            if clip.start < to && to < clip.end { n += 1 }
297	        }
298	        return n
299	    }
