303	/// What Switch by Speaker writes (spec §11 SW-23): the planned shots as one undo step "Switch by
304	/// Speaker" on a Program track — a new one directly in front of the front-most angle, or the
305	/// named track cleared over the range (Replace the shots on) — with the angles hidden, or their
306	/// pictures switched off, inside the range only. Clip ▸ Switch by Speaker…
307	/// (`SwitchSpeakerSheetController`) and `switch_by_speaker` (`AgentServer+Switch.swift`) both
308	/// write through `edit`.
309	///
310	/// Every op is tried ONE at a time on the container's handle through `SwitchAngle.Trial`
311	/// (`applying([ReelOp])` does not stop at a refusal), so the ids a later op names — the Program
312	/// track's, a split's second half — are the ones the commit will mint, and the first refusal
313	/// refuses the whole switch with nothing committed. Names no `rc_*`.
314	extension SpeakerSwitch {
315	    static let programName = "Program"
316	
317	    /// The ops, the Program track they write to, how many `copy_pieces` they hold, and the
318	    /// selection to set after them (SW-23 (f)).
319	    struct Edit {
320	        let ops: [ReelOp]
321	        let track: UInt32
322	        let copies: Int
323	        let selection: Set<UInt32>
324	    }
325	
326	    enum EditAnswer {
327	        case edit(Edit)
328	        case refused(String)
329	    }
330	
331	    /// SW-23 (g): two or more angles in SW-20's defaults, and a selected media clip whose sound
332	    /// is on and whose media has audio.
333	    static func canOffer(_ selection: [ClipSnapshot], in snapshot: ProjectSnapshot) -> Bool {
334	        guard defaults(selection: selection, in: snapshot).angles.count >= 2 else { return false }
335	        return selection.contains { clip in
336	            guard case .media = clip.source, clip.enabled.audio else { return false }
337	            return snapshot.media(for: clip)?.hasAudio == true
338	        }
339	    }
340	
341	    /// SW-23 (d): "Mute the cameras' own sound" is on by default when no microphone is an angle.
342	    static func muteDefault(_ input: Input) -> Bool {
343	        let angles = Set(input.angles.map(\.track))
344	        return !input.microphones.contains { angles.contains($0.track) }
345	    }
346	
347	    /// SW-23 (e): the tracks Replace the shots on may name, front first.
348	    static func replaceable(_ input: Input, selection: Set<UInt32>, in snapshot: ProjectSnapshot)
349	        -> [UInt32]
350	    {
351	        snapshot.tracks.reversed().map(\.id).filter {
352	            replaceRefusal($0, input: input, selection: selection, in: snapshot) == nil
353	        }
354	    }
355	
356	    /// The first of SW-23 (e)'s tests `track` fails, in its sentence; nil when it qualifies.
357	    static func replaceRefusal(
358	        _ track: UInt32, input: Input, selection: Set<UInt32>, in snapshot: ProjectSnapshot
359	    ) -> String? {
360	        let lead = "Track \(track) cannot take the shots: "
361	        guard let found = snapshot.track(track) else { return "no track with id \(track)" }
362	        if found.locked { return lead + "it is locked." }
363	        let clips = snapshot.clips(onTrack: track)
364	        if clips.contains(where: { selection.contains($0.id) }) {
365	            return lead + "it holds a selected clip."
366	        }
367	        guard let front = input.angles.first?.track,
368	            let frontIndex = snapshot.trackIndex(of: front),
369	            let index = snapshot.trackIndex(of: track), index > frontIndex
370	        else { return lead + "it is not in front of the angles." }
371	        let over = clips.filter { $0.end > input.from && $0.start < input.to }
372	        if over.isEmpty {
373	            let a = ReelTime.format(input.from, fps: input.fps, frames: true)
374	            let b = ReelTime.format(input.to, fps: input.fps, frames: true)
375	            return lead + "it has nothing between \(a) and \(b) to replace."
376	        }
377	        let played = Set(
378	            input.angles.flatMap(\.clips).compactMap { snapshot.clip($0.clip)?.source.mediaID })
379	        if let stranger = over.first(where: { clip in
380	            guard case .media = clip.source, let media = clip.source.mediaID else { return true }
381	            return !played.contains(media)
382	        }) {
383	            return lead + "clip \(stranger.id) is not a piece of an angle."
384	        }
385	        return nil
386	    }
387	
388	    /// SW-23's ops for `shots` (a `plan`'s, every shot's angle covering its span) over `input`'s
389	    /// range, tried on `container`, the handle of the container being edited. `replacing` is
390	    /// Replace's track, already through `replaceRefusal`. Throws only the core's invalid input.
391	    static func edit(
392	        _ shots: [Shot], input: Input, muteCameras: Bool, replacing: UInt32?,
393	        selection: Set<UInt32>, in container: ReelProject
394	    ) throws -> EditAnswer {
395	        let snapshot = container.snapshot
396	        let (from, to) = (input.from, input.to)
397	        let angles = input.angles.map(\.track)
398	        guard let front = angles.first, let frontIndex = snapshot.trackIndex(of: front) else {
399	            return .refused(
400	                "Switch by Speaker needs at least two angles: tracks holding a selected clip "
401	                    + "with a picture.")
402	        }
403	
404	        // (h): a linked angle clip crossing the range, before any op.
405	        for track in angles {
406	            for clip in SwitchAngle.pictureClips(on: track, in: snapshot)
407	            where clip.end > from && clip.start < to {
408	                if let partner = clip.linked {
409	                    return .refused(
410	                        "clip \(clip.id) on track \(track) is linked to clip \(partner) (Detach "
411	                            + "Audio's pair); Switch by Speaker cuts between cameras with no link "
412	                            + "— Attach Audio first")
413	                }
414	            }
415	        }
416	
417	        var trial = SwitchAngle.Trial(project: container)
418	        var chosen = selection
419	        func refusal(_ op: ReelOp) throws -> String? {
420	            try trial.require(op).map { "Switch by Speaker was refused at \(op.name): \($0)" }
421	        }
422	        /// Splits `clip` at `at`, a selected clip's new half joining the selection (f).
423	        func split(_ clip: ClipSnapshot, at: Ticks) throws -> String? {
424	            let known = Set(trial.project.snapshot.clips.map(\.id))
425	            if let why = try refusal(.split(clips: [clip.id], at: at)) { return why }
426	            if chosen.contains(clip.id) {
427	                chosen.formUnion(trial.project.snapshot.clips.map(\.id).filter { !known.contains($0) })
428	            }
429	            return nil
430	        }
431	        func inside(_ clip: ClipSnapshot) -> Bool { clip.start >= from && clip.end <= to }
432	
433	        // (a) The destination.
434	        let destination: UInt32
435	        if let replacing {
436	            for at in [from, to] {
437	                for clip in trial.project.snapshot.clips(onTrack: replacing)
438	                where clip.start < at && at < clip.end {
439	                    if let why = try split(clip, at: at) { return .refused(why) }
440	                }
441	            }
442	            let cleared = trial.project.snapshot.clips(onTrack: replacing).filter(inside).map(\.id)
443	            if !cleared.isEmpty, let why = try refusal(.delete(clips: cleared)) {
444	                return .refused(why)
445	            }
446	            destination = replacing
447	        } else {
448	            let before = Set(snapshot.tracks.map(\.id))
449	            let add = ReelOp.addTrack(index: frontIndex + 1, name: programName)
450	            if let why = try refusal(add) { return .refused(why) }
451	            guard let made = trial.project.snapshot.tracks.first(where: { !before.contains($0.id) })
452	            else { return .refused("Switch by Speaker was refused at add_track: no track was added.") }
453	            destination = made.id
454	        }
455	
456	        // (b) One copy_pieces per angle clip, in the order of its first range.
457	        var ranges: [UInt32: [(from: Ticks, to: Ticks)]] = [:]
458	        var order: [UInt32] = []
459	        for shot in shots {
460	            for piece in SwitchAngle.pieceRanges(
461	                angle: shot.angle, from: shot.start, to: shot.end, in: snapshot)
462	            {
463	                if ranges[piece.clip] == nil { order.append(piece.clip) }
464	                ranges[piece.clip, default: []].append((piece.from, piece.to))
465	            }
466	        }
467	        order.sort { (ranges[$0]?.first?.from ?? 0) < (ranges[$1]?.first?.from ?? 0) }
468	        for clip in order {
469	            let op = ReelOp.copyPieces(
470	                clip: clip, track: destination, ranges: ranges[clip] ?? [], video: true,
471	                audio: false)
472	            if let why = try refusal(op) { return .refused(why) }
473	        }
474	
475	        // (c), (d) The angles, front first.
476	        let microphones = Set(input.microphones.map(\.track))
477	        for track in angles {
478	            let mute = muteCameras && !microphones.contains(track)
479	            let now = trial.project.snapshot
480	            let pictures = SwitchAngle.pictureClips(on: track, in: now)
481	            let ids = Set(pictures.map(\.id))
482	            let all = now.clips(onTrack: track)
483	            if !all.isEmpty, all.allSatisfy({ ids.contains($0.id) && inside($0) }) {
484	                if now.track(track)?.hidden != true,
485	                    let why = try refusal(.setTrack(track: track, hidden: true))
486	                {
487	                    return .refused(why)
488	                }
489	                for clip in pictures where mute && clip.enabled.audio {
490	                    if let why = try refusal(.setEnabled(clip: clip.id, audio: false)) {
491	                        return .refused(why)
492	                    }
493	                }
494	                continue
495	            }
496	            for at in [from, to] {
497	                for clip in SwitchAngle.pictureClips(on: track, in: trial.project.snapshot)
498	                where clip.start < at && at < clip.end {
499	                    if let why = try split(clip, at: at) { return .refused(why) }
500	                }
501	            }
502	            for clip in SwitchAngle.pictureClips(on: track, in: trial.project.snapshot)
503	            where inside(clip) {
504	                let video: Bool? = clip.enabled.video ? false : nil
505	                let audio: Bool? = mute && clip.enabled.audio ? false : nil
506	                guard video != nil || audio != nil else { continue }
507	                if let why = try refusal(.setEnabled(clip: clip.id, video: video, audio: audio)) {
508	                    return .refused(why)
509	                }
510	            }
511	        }
512	        return .edit(
513	            Edit(ops: trial.ops, track: destination, copies: order.count, selection: chosen))
514	    }
515	}
