518	/// Switch by Speaker's one reader (spec §11 SW-20, SW-25), shaped like
519	/// `AudioSync.read`: the edited project's snapshot and plan, and each
520	/// microphone's loudness and speech caches, read onto the range's 10 ms grid
521	/// through `ClipLevelSeries`. A missing cache file is "still being analysed",
522	/// never silence. In the faces mode (SW8) it also reads each face speaker's
523	/// angle through `readFaces` (`SpeakerSwitch+Faces.swift`).
524	extension SpeakerSwitch {
525	    /// `clips` nil: the document's selection. `pairing` nil: SW-20's
526	    /// defaults. `range` nil: the In–Out range, else the selected angle
527	    /// clips' extent. nil only when the edited project's plan cannot be read.
528	    static func read(
529	        from document: ProjectDocument, clips: [UInt32]?, pairing: Pairing?,
530	        range: (from: Ticks, to: Ticks)?, settings: Settings
531	    ) -> Input? {
532	        let project = document.editedProject
533	        guard let plan = project.plan else { return nil }
534	        let snapshot = project.snapshot
535	        var seen: Set<UInt32> = []
536	        let selection = (clips ?? document.selection.sorted())
537	            .filter { seen.insert($0).inserted }
538	            .compactMap { snapshot.clip($0) }
539	        let implied = defaults(selection: selection, in: snapshot)
540	        let pairing = pairing ?? implied.pairing
541	
542	        // A named pairing's microphones are the tracks it names that hold a
543	        // selected sounding clip, a detached camera sound included (SW-20).
544	        let front = snapshot.tracks.reversed().map(\.id)
