664	/// Mouth activity (road map "creator-jobs" SW8, spec §11 SW-81, SW-82): who
665	/// is talking when one microphone hears everyone, from each angle's cached
666	/// `faces` (CJ-30). The largest face is the angle's person; a sample's opening
667	/// is its mouth's gap over its width; activity is the population standard
668	/// deviation of the openings over `window` centred on a sample; a speech step
669	/// is the top angle's when it is `ratio` × the next and above `floor`, else
670	/// crosstalk. Pure: reads no document, file or clock (SW-25); names no `rc_*`.
671	enum FaceActivity {
672	    /// Seconds, centred (SW-81).
673	    static let window: Double = 0.5
674	    /// The top angle's activity is at least this times the next's.
675	    static let ratio: Double = 1.5
676	    /// The standard deviation of gap/width the top must exceed; PROVISIONAL
677	    /// until SW-S3 measures S-PC2 (SW-88).
678	    static let floor: Double = 0.02
679	    /// Seconds: the faces mode's `min_shot` default, SW-S3's middle band (SW-82).
680	    static let minShot: Double = 3.0
681	    /// The first sentence of the sheet's summary and the tool's `note` in the
682	    /// faces mode (SW-82).
683	    static let hedge = "Faces guess who is talking; check the cuts."
684	
685	    /// The face with the largest width × height; ties go to the first in
686	    /// CJ-31's order. nil for no face.
687	    static func largest(_ faces: [AnalysisFaces.Face]) -> AnalysisFaces.Face? {
688	        var best: AnalysisFaces.Face?
689	        var area = -Double.infinity
690	        for face in faces {
691	            let a = Double(face.width) * Double(face.height)
692	            if best == nil || a > area {
693	                best = face
694	                area = a.isNaN ? -.infinity : a
695	            }
696	        }
697	        return best
698	    }
699	
700	    /// The largest face's `mouthGap / mouthWidth`; nil for no frame (pts −1),
701	    /// no face, a non-finite gap or width, or a width ≤ 0.
702	    static func opening(_ sample: AnalysisFaces.Sample) -> Double? {
703	        guard sample.pts >= 0, let face = largest(sample.faces) else { return nil }
704	        let gap = Double(face.mouthGap), width = Double(face.mouthWidth)
705	        guard gap.isFinite, width.isFinite, width > 0 else { return nil }
706	        return gap / width
707	    }
708	
709	    /// Samples each side of the centre: ⌊window/2 · rate⌋ (2 at 10 a second,
710	    /// 1 at 5).
711	    static func halfWidth(rate: Double) -> Int {
712	        guard rate.isFinite, rate > 0 else { return 0 }
713	        return Int((window / 2 * rate + 1e-9).rounded(.down))
714	    }
715	
716	    /// Per index c, the population standard deviation of the non-nil
717	    /// openings in c − half … c + half (clipped to the series); nil when
718	    /// fewer than two are there.
719	    static func activities(_ openings: [Double?], half: Int) -> [Double?] {
720	        let n = openings.count
721	        var out = [Double?](repeating: nil, count: n)
722	        for c in 0..<n {
723	            var values: [Double] = []
724	            for k in max(0, c - half)...min(n - 1, c + half) {
725	                if let v = openings[k] { values.append(v) }
726	            }
727	            guard values.count >= 2 else { continue }
728	            let mean = values.reduce(0, +) / Double(values.count)
729	            let variance = values.reduce(0) { $0 + ($1 - mean) * ($1 - mean) } / Double(values.count)
730	            out[c] = variance.squareRoot()
731	        }
732	        return out
733	    }
734	
735	    /// A step's label over the contesting angles, front first: no speech or
736	    /// no activity → nobody; else the top angle (ties: the front-most) when
737	    /// top ≥ `ratio` × the next (0 when alone) and top > `floor`, otherwise
738	    /// crosstalk. `person` names the ANGLE track.
739	    static func label(
740	        speech: Bool, activities: [(angle: UInt32, activity: Double?)], ratio: Double,
741	        floor: Double
742	    ) -> SpeakerSwitch.Label {
743	        guard speech else { return .nobody }
744	        var top: (angle: UInt32, value: Double)?
745	        var next = 0.0
746	        for case let (angle, value?) in activities {
747	            if let current = top {
748	                if value > current.value {
749	                    next = current.value
750	                    top = (angle, value)
751	                } else if value > next {
752	                    next = value
753	                }
754	            } else {
755	                top = (angle, value)
756	            }
757	        }
758	        guard let top else { return .nobody }
759	        return top.value >= ratio * next && top.value > floor ? .person(top.angle) : .crosstalk
760	    }
761	}
