924	/// Who speaks when, as `reframe_clip {follow: speaker}` is handed it (road map
925	/// "creator-jobs" VR6a, spec §11 VR-60 (c)): SW-21's labels and SW-22 (a)–(e)
926	/// read exactly as `shots` reads them, but on the labels themselves, not on
927	/// angles, so the framing and Switch by Speaker agree about who is talking.
928	///
929	/// - the crosstalk bridge and the nobody bridge (`bridgedRuns`, SW-22 (a));
930	/// - a person run of at least `minTurn` starts that microphone's turn, a
931	///   crosstalk run of at least `crosstalkMin` one turn per microphone active
932	///   at any of its crosstalk steps; nobody and shorter runs hold;
933	/// - each start at `snap(onset − lead)`, never before the last start or the
934	///   range's start; the first start is the range's start;
935	/// - each turn ends at the next start, the last at the range's end, so the
936	///   turns tile the range (crosstalk turns share one span).
937	///
938	/// Pure (SW-25): reads no document, file or clock.
939	extension SpeakerSwitch {
940	    /// One microphone's turn: `mic` is its TRACK, `[from, to)` range ticks.
941	    struct Turn: Equatable {
942	        let mic: UInt32
943	        let from: Ticks
944	        let to: Ticks
945	    }
946	
947	    /// The turns of `input`'s read microphones over its range (this file's
948	    /// doc); empty when no run qualifies.
949	    static func turns(_ input: Input) -> [Turn] {
950	        let step = stepTicks
951	        guard step > 0, input.to > input.from else { return [] }
952	        let count = Int((input.to - input.from) / step)
953	        let microphones = input.microphones.filter { $0.level.count == count }
954	        let settings = input.settings
955	        func ticks(_ seconds: Double) -> Ticks {
956	            Ticks((seconds * Double(ReelTime.perSecond)).rounded())
957	        }
958	        let sets = activeSets(microphones, settings: settings)
959	        let steps = labels(microphones, settings: settings)
960	        let order = microphones.map(\.track)
961	
962	        var starts: [(mics: [UInt32], start: Ticks)] = []
963	        for run in bridgedRuns(steps, settings: settings) {
964	            let length = Ticks(run.end - run.start) * step
965	            var mics: [UInt32] = []
966	            switch run.label {
967	            case .nobody: break
968	            case .person(let mic):
969	                if length >= ticks(settings.minTurn) { mics = [mic] }
970	            case .crosstalk:
971	                guard length >= ticks(settings.crosstalkMin) else { break }
972	                var active = Set<UInt32>()
973	                for k in run.start..<min(run.end, sets.count) where sets[k].count >= 2 {
974	                    active.formUnion(sets[k])
975	                }
976	                mics = order.filter { active.contains($0) }
977	            }
978	            guard !mics.isEmpty, mics != starts.last?.mics else { continue }
979	            let at = max(
980	                starts.last?.start ?? input.from, input.from,
981	                ReelTime.snapToFrame(
982	                    input.from + Ticks(run.start) * step - ticks(settings.lead), fps: input.fps))
983	            if starts.last?.start == at {
984	                starts.removeLast()
985	                if starts.last?.mics == mics { continue }
986	            }
987	            starts.append((mics, at))
988	        }
989	        guard !starts.isEmpty else { return [] }
990	        starts[0].start = input.from
991	        var out: [Turn] = []
992	        for (index, start) in starts.enumerated() {
993	            let end = index + 1 < starts.count ? min(starts[index + 1].start, input.to) : input.to
994	            guard end > start.start else { continue }
995	            for mic in start.mics { out.append(Turn(mic: mic, from: start.start, to: end)) }
996	        }
997	        return out
998	    }
